const input = $input.first().json;
const body = input.body || input;
const payload = body.payload || body;

const commentText = payload.message || payload.comment_text || payload.text || '';
const commentId = payload.comment_id || payload.id || '';
const postId = payload.post_id || payload.object_id || '';
const pageId = payload.page_id || payload.recipient_id || '';
const senderName = payload.sender_name || payload.from?.name || 'Usuario';
const senderId = payload.sender_id || payload.from?.id || '';
const platform = payload.platform || (payload.object === 'instagram' ? 'instagram' : 'facebook');

return [{
  json: {
    core_workflow_id: 'CUSTOMER_SERVICE_CORE_ID',
    channel: 'meta-comment',
    conversation_id: String(pageId + ':' + postId + ':' + commentId),
    user_id: String(senderId || ''),
    message: commentText,
    attachments: [],
    metadata: {
      comment_id: commentId,
      post_id: postId,
      page_id: pageId,
      platform: platform,
      sender_name: senderName,
      sender_id: senderId
    }
  }
}];

const item = $input.first().json;
const meta = item.metadata || {};

// Check if Meta toolkit is connected in Composio
const hasMetaToolkit = false; // TODO: set to true once Meta Business Suite toolkit is connected

if (!hasMetaToolkit) {
  return [{
    json: {
      ...item,
      reply_sent: false,
      note: 'Meta toolkit not connected in Composio yet. Reply logged for manual action.'
    }
  }];
}

// When connected, use Composio Meta tools to reply to comment
// This would be an HTTP call to the Composio MCP or a direct Meta Graph API call
return [{
  json: {
    ...item,
    reply_sent: true,
    note: 'Auto-reply would be sent via Composio Meta tools.'
  }
}];
